
#include <stdint.h>

#include "bootloader.h"
#include "flash_mock.h"

/* Exact 76-byte stream generated by Python */
static const uint8_t host_stream[76] =
{
    0xAAU, 0x55U, 0x01U, 0x01U, 0x00U, 0x00U, 0x00U, 0x08U,
    0x00U, 0x00U, 0x00U, 0x10U, 0xF4U, 0xA7U, 0xFDU, 0x67U,
    0xEDU, 0xEDU, 0xD5U, 0xB0U, 0xAAU, 0x55U, 0x01U, 0x03U,
    0x00U, 0x01U, 0x00U, 0x14U, 0x00U, 0x00U, 0x00U, 0x00U,
    0x10U, 0x11U, 0x12U, 0x13U, 0x14U, 0x15U, 0x16U, 0x17U,
    0x18U, 0x19U, 0x1AU, 0x1BU, 0x1CU, 0x1DU, 0x1EU, 0x1FU,
    0xA7U, 0x6EU, 0xE4U, 0x47U, 0xAAU, 0x55U, 0x01U, 0x04U,
    0x00U, 0x02U, 0x00U, 0x00U, 0x8CU, 0x9AU, 0x00U, 0xA8U,
    0xAAU, 0x55U, 0x01U, 0x05U, 0x00U, 0x03U, 0x00U, 0x00U,
    0xB0U, 0x38U, 0x43U, 0x2FU
};

/* Debugger result variables */
volatile uint8_t start_result = 0xFFU;
volatile uint8_t write_state = 0xFFU;
volatile uint8_t flash_read_result = 0xFFU;
volatile uint8_t flash_match = 0U;
volatile uint8_t verify_result = 0xFFU;
volatile uint8_t jump_result = 0xFFU;

static void InjectRange(uint32_t start, uint32_t count)
{
    uint32_t i;

    for (i = start; i < (start + count); i++)
    {
        Bootloader_TestInjectByte(host_stream[i]);
    }
}

int main(void)
{
    uint8_t readback[16];
    uint32_t i;

    Bootloader_Init();

    /* TEST 1: Python START_UPDATE packet */
    InjectRange(0U, 20U);
    start_result = Bootloader_GetState();

    /* TEST 2: Python WRITE_DATA packet */
    InjectRange(20U, 32U);
    write_state = Bootloader_GetState();

    /* TEST 3: Read back simulated flash */
    flash_read_result = (uint8_t)FlashMock_Read(
        0U,
        readback,
        16U
    );

    flash_match = 1U;

    for (i = 0U; i < 16U; i++)
    {
        if (readback[i] != (uint8_t)(0x10U + i))
        {
            flash_match = 0U;
        }
    }

    /* TEST 4: Python VERIFY packet */
    InjectRange(52U, 12U);
    verify_result = Bootloader_GetState();

    /* TEST 5: Python JUMP_APP packet */
    InjectRange(64U, 12U);
    jump_result = Bootloader_GetState();

    /* Stop for debugger inspection */
    while (1)
    {
    }
}
